"use strict";
export function calculateProjectedHealthFactor(currentCollateral, additionalCollateral, currentBorrow, additionalBorrow, collateralPriceUsd, loanPriceUsd, lltvPercent, isRepay) {
  const newCollateral = isRepay ? Math.max(0, currentCollateral - additionalCollateral) : currentCollateral + additionalCollateral;
  const newBorrow = isRepay ? Math.max(0, currentBorrow - additionalBorrow) : currentBorrow + additionalBorrow;
  if (newBorrow === 0) return Infinity;
  const collateralValueUsd = newCollateral * collateralPriceUsd;
  const borrowValueUsd = newBorrow * loanPriceUsd;
  const maxBorrowUsd = collateralValueUsd * (lltvPercent / 100);
  return maxBorrowUsd / borrowValueUsd;
}
export function formatHealthFactor(hf) {
  if (hf === Infinity || !isFinite(hf)) return "\u221E";
  if (hf < 0) return "0.00";
  return hf.toFixed(2);
}
export function getHealthFactorColor(hf) {
  if (hf === Infinity || !isFinite(hf)) return "$statusSuccess";
  if (hf < 1) return "$statusCritical";
  if (hf < 1.2) return "$statusCritical";
  if (hf < 1.5) return "$statusWarning";
  return "$statusSuccess";
}
export function formatPriceWithSignificantDigits(value, minSignificantDigits = 3) {
  if (value === 0 || !isFinite(value)) return "0";
  const absValue = Math.abs(value);
  if (absValue >= 1e3) {
    return value.toFixed(2);
  }
  if (absValue >= 1) {
    const integerDigits = Math.floor(Math.log10(absValue)) + 1;
    const decimalsNeeded2 = Math.max(2, minSignificantDigits - integerDigits);
    return value.toFixed(decimalsNeeded2);
  }
  const magnitude = Math.floor(Math.log10(absValue));
  const decimalsNeeded = Math.abs(magnitude) + minSignificantDigits - 1;
  return value.toFixed(Math.min(decimalsNeeded, 10));
}
