"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { useMorphoBorrowTransaction } from "hooks/morpho";
import { useCallback, useEffect } from "react";
import { ArrowRight, ArrowUpRight, CheckCircle, X, XCircle } from "react-feather";
import { Button, Flex, SpinningLoader, Text, styled, useSporeColors } from "ui/src";
import { Modal } from "uniswap/src/components/modals/Modal";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { formatHealthFactor, getHealthFactorColor } from "../Market/utils/healthFactorUtils";
const EXPLORER_URL = "https://abscan.org";
const CloseIcon = styled(Flex, {
  cursor: "pointer",
  padding: "$spacing8",
  borderRadius: "$roundedFull",
  hoverStyle: { backgroundColor: "$surface2" }
});
const ModalHeader = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing24"
});
const SummaryCard = styled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing24",
  flexDirection: "column",
  gap: "$spacing8",
  width: "100%",
  marginBottom: "$spacing24"
});
const PairHeader = styled(Flex, {
  flexDirection: "row",
  alignItems: "center",
  gap: "$gap8",
  marginBottom: "$spacing24"
});
const Badge = styled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8"
});
const ArrowPill = styled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  padding: "$spacing4",
  alignItems: "center",
  justifyContent: "center",
  width: 24,
  height: 24
});
const PermitSection = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  marginBottom: "$spacing24"
});
const ProgressRow = styled(Flex, {
  flexDirection: "row",
  width: "100%",
  gap: "$gap8",
  marginBottom: "$spacing12"
});
const ProgressSegment = styled(Flex, {
  height: "4px",
  borderRadius: "$roundedFull",
  flex: 1,
  variants: {
    status: {
      active: { backgroundColor: "$accent1" },
      // Blue
      completed: { backgroundColor: "$greenVibrant" },
      // Green (assuming variable exists)
      pending: { backgroundColor: "$surface3" }
      // Gray
    }
  }
});
const FooterRow = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%"
});
const ExplorerLink = styled(Flex, {
  flexDirection: "row",
  alignItems: "center",
  gap: "$gap4",
  cursor: "pointer"
});
const DoneButton = styled(Button, {
  width: "100%",
  borderRadius: "$rounded20",
  py: "$spacing24",
  marginBottom: "$spacing16"
});
const InfoRow = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing8"
});
export default function BorrowConfirmModal({
  isOpen,
  onClose,
  marketId,
  collateralAmount,
  borrowAmount,
  collateralToken,
  borrowToken,
  lltvPercent,
  transactionType,
  currentHealthFactor = Infinity,
  projectedHealthFactor = Infinity
}) {
  const colors = useSporeColors();
  const chainId = UniverseChainId.Mainnet;
  const {
    state,
    isCapabilitiesLoading,
    supplyCollateralAndBorrow,
    repay,
    withdrawCollateral,
    addCollateral,
    borrowMore,
    reset
  } = useMorphoBorrowTransaction(chainId);
  const parsedCollateral = parseFloat(collateralAmount) || 0;
  const parsedBorrow = parseFloat(borrowAmount) || 0;
  const isRepayFlow = transactionType === "repay";
  const executeTransaction = useCallback(async () => {
    if (isRepayFlow) {
      if (parsedBorrow > 0) {
        await repay(marketId, borrowAmount);
      }
      if (parsedCollateral > 0) {
        await withdrawCollateral(marketId, collateralAmount);
      }
    } else {
      const hasCollateral = parsedCollateral > 0;
      const hasBorrow = parsedBorrow > 0;
      if (hasCollateral && hasBorrow) {
        await supplyCollateralAndBorrow(marketId, collateralAmount, borrowAmount);
      } else if (hasCollateral) {
        await addCollateral(marketId, collateralAmount);
      } else if (hasBorrow) {
        await borrowMore(marketId, borrowAmount);
      }
    }
  }, [
    isRepayFlow,
    parsedBorrow,
    parsedCollateral,
    collateralAmount,
    borrowAmount,
    marketId,
    supplyCollateralAndBorrow,
    repay,
    withdrawCollateral,
    addCollateral,
    borrowMore
  ]);
  useEffect(() => {
    if (isOpen && state.status === "idle" && !isCapabilitiesLoading) {
      executeTransaction();
    }
  }, [isOpen, state.status, isCapabilitiesLoading, executeTransaction]);
  useEffect(() => {
    if (!isOpen) {
      reset();
    }
  }, [isOpen, reset]);
  const handleClose = () => {
    reset();
    onClose();
  };
  const handleViewOnExplorer = () => {
    const hash = state.txHash || state.approvalTxHash;
    if (hash) {
      window.open(`${EXPLORER_URL}/tx/${hash}`, "_blank");
    }
  };
  const isProcessing = isCapabilitiesLoading || state.status === "approving_collateral" || state.status === "supplying_collateral" || state.status === "borrowing" || state.status === "approving_repay" || state.status === "repaying" || state.status === "withdrawing_collateral";
  const isSuccess = state.status === "success";
  const isError = state.status === "error";
  const getStepText = () => {
    if (isCapabilitiesLoading) return "Checking wallet capabilities...";
    if (state.status === "approving_collateral") return "Approving collateral...";
    if (state.status === "supplying_collateral") return "Supplying collateral...";
    if (state.status === "borrowing") return "Executing borrow...";
    if (state.status === "approving_repay") return "Approving repayment...";
    if (state.status === "repaying") return "Repaying loan...";
    if (state.status === "withdrawing_collateral") return "Withdrawing collateral...";
    if (state.status === "success") return "Transaction complete!";
    if (state.status === "error") return state.error || "Transaction failed";
    return "Preparing...";
  };
  const getProgressStep = () => {
    if (isRepayFlow) {
      if (state.status === "approving_repay") return 1;
      if (state.status === "repaying") return 2;
      if (state.status === "withdrawing_collateral") return 3;
      return 0;
    }
    if (state.status === "approving_collateral") return 1;
    if (state.status === "supplying_collateral") return 2;
    if (state.status === "borrowing") return 3;
    return 0;
  };
  const getTotalSteps = () => {
    if (isRepayFlow) {
      const steps = (parsedBorrow > 0 ? 2 : 0) + (parsedCollateral > 0 ? 1 : 0);
      return Math.max(steps, 1);
    }
    const hasCollateral = parsedCollateral > 0;
    const hasBorrow = parsedBorrow > 0;
    if (hasCollateral && hasBorrow) return 3;
    if (hasCollateral) return 2;
    if (hasBorrow) return 1;
    return 0;
  };
  const totalSteps = getTotalSteps();
  const progressStep = getProgressStep();
  return <Modal
    name={"BorrowConfirmModal"}
    isModalOpen={isOpen}
    onClose={handleClose}
    backgroundColor={colors.surface1?.val ?? "#1a1a1a"}
    maxWidth={480}
    padding="$spacing24"
  >
      <ModalHeader>
        <Text variant="heading2" color="$neutral1">
          {isSuccess ? "Success" : isError ? "Failed" : "Confirm"}
        </Text>
        <CloseIcon onPress={handleClose}>
          <X size={24} color={colors.neutral2?.val ?? "#888"} />
        </CloseIcon>
      </ModalHeader>

      <SummaryCard>
        <PairHeader>
          <Flex flexDirection="row" alignItems="center" mr="$spacing4">
            <PortfolioLogo
    chainId={chainId}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.symbol ?? ""}
    images={[getTokenLogoUrl(collateralToken.id) || void 0]}
    size={24}
    style={{ marginRight: -8, zIndex: 2 }}
  />
            <PortfolioLogo
    chainId={chainId}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.symbol ?? ""}
    images={[getTokenLogoUrl(borrowToken.id) || void 0]}
    size={24}
    style={{ zIndex: 1 }}
  />
          </Flex>
          <Text variant="heading3" color="$neutral1">
            {collateralToken.symbol}/{borrowToken.symbol}
          </Text>
          <Badge>
            <Text variant="body4" color="$neutral2">
              {lltvPercent}%
            </Text>
          </Badge>
          <ArrowPill>
            <ArrowUpRight size={12} color={colors.neutral2?.val ?? "#888"} />
          </ArrowPill>
        </PairHeader>

        {isRepayFlow ? <>
            {parsedBorrow > 0 && <>
                <Text variant="body2" color="$neutral2" mb="$spacing8">
                  Repay Loan
                </Text>
                <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
                  <Flex flexDirection="row" alignItems="center">
                    <Text variant="heading2" color="$neutral1">
                      {parsedBorrow}
                    </Text>
                    <Text variant="heading2" color="$neutral2" ml="$spacing4">
                      {borrowToken.symbol}
                    </Text>
                  </Flex>
                  <PortfolioLogo
    chainId={chainId}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.symbol ?? ""}
    images={[getTokenLogoUrl(borrowToken.id) || void 0]}
    size={24}
  />
                </Flex>
              </>}

            {parsedCollateral > 0 && <>
                <Text variant="body2" color="$neutral2" mt={parsedBorrow > 0 ? "$spacing16" : void 0} mb="$spacing8">
                  Withdraw Collateral
                </Text>
                <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
                  <Flex flexDirection="row" alignItems="center">
                    <Text variant="heading2" color="$neutral1">
                      {parsedCollateral}
                    </Text>
                    <Text variant="heading2" color="$neutral2" ml="$spacing4">
                      {collateralToken.symbol}
                    </Text>
                  </Flex>
                  <PortfolioLogo
    chainId={chainId}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.symbol ?? ""}
    images={[getTokenLogoUrl(collateralToken.id) || void 0]}
    size={24}
  />
                </Flex>
              </>}
          </> : <>
            {parsedCollateral > 0 && <>
                <Text variant="body2" color="$neutral2" mb="$spacing8">
                  Supply Collateral
                </Text>

                <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
                  <Flex flexDirection="row" alignItems="center">
                    <Text variant="heading3" color="$neutral1">
                      {parsedCollateral}
                    </Text>
                    <Text variant="heading3" color="$neutral2" ml="$spacing4">
                      {collateralToken.symbol}
                    </Text>
                  </Flex>
                  <PortfolioLogo
    chainId={chainId}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.symbol ?? ""}
    images={[getTokenLogoUrl(collateralToken.id) || void 0]}
    size={24}
  />
                </Flex>
              </>}

            {parsedBorrow > 0 && <>
                <Text
    variant="body2"
    color="$neutral2"
    mt={parsedCollateral > 0 ? "$spacing16" : void 0}
    mb="$spacing8"
  >
                  Borrow
                </Text>
                <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
                  <Flex flexDirection="row" alignItems="center">
                    <Text variant="heading2" color="$neutral1">
                      {borrowAmount}
                    </Text>
                    <Text variant="heading2" color="$neutral2" ml="$spacing4">
                      {borrowToken.symbol}
                    </Text>
                  </Flex>
                  <PortfolioLogo
    chainId={chainId}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.symbol ?? ""}
    images={[getTokenLogoUrl(borrowToken.id) || void 0]}
    size={24}
  />
                </Flex>
              </>}
          </>}
      </SummaryCard>

      <InfoRow>
        <Text variant="body3" color="$neutral2">
          Health Factor
        </Text>
        <Flex row alignItems="center" gap="$gap4">
          <Text variant="body3" color={getHealthFactorColor(currentHealthFactor)}>
            {formatHealthFactor(currentHealthFactor)}
          </Text>
          <ArrowRight size={14} color={colors.neutral3?.val ?? "#666"} />
          <Text variant="body3" color={getHealthFactorColor(projectedHealthFactor)}>
            {formatHealthFactor(projectedHealthFactor)}
          </Text>
        </Flex>
      </InfoRow>

      {isProcessing && <>
          <PermitSection>
            <Flex flexDirection="row" alignItems="center">
              <Text variant="body2" color="$neutral1">
                {getStepText()}
              </Text>
            </Flex>
            <SpinningLoader size={20} color={colors.accent1?.val ?? "#3b82f6"} />
          </PermitSection>

          <ProgressRow>
            {Array.from({ length: totalSteps }, (_, i) => {
    const step = i + 1;
    const status = progressStep >= step ? progressStep > step ? "completed" : "active" : "pending";
    return <ProgressSegment key={step} status={status} />;
  })}
          </ProgressRow>

          <Text variant="body3" color="$neutral2" mb="$spacing16">
            Step {progressStep}/{totalSteps} - Confirm in wallet
          </Text>
        </>}

      {isSuccess && <Flex flexDirection="column" alignItems="center" gap="$gap16" mb="$spacing24">
          <CheckCircle size={48} color={colors.statusSuccess?.val ?? "#22c55e"} />
          <Text variant="body2" color="$neutral1" textAlign="center">
            Your transaction was successful!
          </Text>
          <DoneButton onPress={handleClose}>
            <Button.Text>Done</Button.Text>
          </DoneButton>
        </Flex>}

      {isError && <Flex flexDirection="column" alignItems="center" gap="$gap16" mb="$spacing24">
          <XCircle size={48} color={colors.statusCritical?.val ?? "#ef4444"} />
          <Text variant="body2" color="$critical" textAlign="center">
            {state.error || "Transaction failed"}
          </Text>
          <DoneButton onPress={handleClose}>
            <Button.Text>Close</Button.Text>
          </DoneButton>
        </Flex>}

      {(state.txHash || state.approvalTxHash) && <FooterRow>
          <Flex opacity={1} hoverStyle={{ opacity: 0.75 }} transition="opacity 0.2s ease-in-out">
            <ExplorerLink onPress={handleViewOnExplorer}>
              <Text variant="body3" color="$neutral2">
                View on explorer
              </Text>
              <ArrowUpRight size={14} color={colors.neutral2?.val ?? "#888"} />
            </ExplorerLink>
          </Flex>
        </FooterRow>}
    </Modal>;
}
